// src/components/Equipment.js
import React, { useState } from 'react';
import styled from 'styled-components';

const EquipmentGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
`;

const EquipmentItem = styled.div`
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 10px;
  background-color: #fff;
  text-align: center;
  cursor: pointer;
  transition: box-shadow 0.3s ease;

  &:hover {
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.1);
  }
`;

const EquipmentImage = styled.img`
  width: 100%;
  height: 200px;
  object-fit: cover;
  border-radius: 8px;
`;

const ExpandedSection = styled.div`
  margin-top: 10px;
  text-align: left;
  background-color: #f9f9f9;
  padding: 10px;
  border-radius: 5px;
  border: 1px solid #ddd;
`;

const Equipment = ({ equipment, handleSelect }) => {
  const [expandedItem, setExpandedItem] = useState(null);

  const toggleExpand = (item) => {
    setExpandedItem(expandedItem === item ? null : item);
  };

  return (
    <EquipmentGrid>
      {equipment.map((item) => (
        <EquipmentItem key={item.id} onClick={() => toggleExpand(item)}>
          <EquipmentImage src={item.Image_URL} alt={item.Name} />
          <h3>{item.Name}</h3>
          <p>Brand: {item.Brand}</p>
          <p>Price: ${item.Price}</p>

          {expandedItem === item && (
            <ExpandedSection>
              <p><strong>Description:</strong> {item.Description || 'No description available.'}</p>
              <a href={item.Link} target="_blank" rel="noopener noreferrer">
                View Product Page
              </a>
              <button onClick={() => handleSelect(item)} style={{ marginTop: '10px' }}>
                Select Item
              </button>
            </ExpandedSection>
          )}
        </EquipmentItem>
      ))}
    </EquipmentGrid>
  );
};

export default Equipment;
